CREATE TEMPORARY VIEW selected_user_exps_${grass_region_without_quote} AS
select
    user_id
    ,exp_group_id
    ,local_date
from
    srdi_mart.dim_sr_data_warehouse_abtest_user_group
where
    grass_region in (${grass_region})
    and local_date between date_add(date(${local_date}), -6) and date(${local_date})
    and is_assignment_log = 1
    and is_rcmd_search_whitelist = 1
;

--sql_divide_splitter--
create temporary view behavior_data_${grass_region_without_quote} as
select
    user_id
    ,order_id
    ,local_date
    ,case when is_ads = true then 'true' else 'false' end as is_ads
    ,array_remove(
        split(
            concat_ws(',', if(reporting_business_line = 'Search' and reporting_module = 'Global Search', 'Global Search', null), algo_tag)
            ,','
        )
        ,''
    ) as scenario_tags
    ,array_remove(
        split(
            concat_ws(',', if(source1_reporting_business_line = 'Search' and source1_reporting_module = 'Global Search', 'Global Search', null), source1_algo_tag)
            ,','
        )
        ,''
    ) as source1_scenario_tags
    ,array_remove(
        split(
            concat_ws(',', if(source2_reporting_business_line = 'Search' and source2_reporting_module = 'Global Search', 'Global Search', null), source2_algo_tag)
            ,','
        )
        ,''
    ) as source2_scenario_tags

    ,sum(operation_cnt) as order_cnt
    ,sum(place_order_gmv) as gmv
from
    srdi_mart.dwd_sr_data_warehouse_platform
where
    grass_region in (${grass_region})
    and local_date between date_add(date(${local_date}), -6) and date(${local_date})
    and operation in ('order')
group by 1, 2, 3, 4, 5, 6, 7
;

--sql_divide_splitter--
create temporary view order_antifraud_tag_${grass_region_without_quote} as
select
    order_id
    ,tag as antifraud_tag -- 0: Brushing, 1: Abuse
from
    szci_antifraud.dws_ob_online_s1_di
where
    grass_region in (${grass_region})
    and grass_date between date_add(date(${local_date}), -6) and date(${local_date})
group by 1, 2
;

--sql_divide_splitter--
create temporary view behavior_data_joined_${grass_region_without_quote} as
select
    user_id
    ,is_ads
    ,array_union(array_union(scenario_tags, COALESCE(source1_scenario_tags, array())), COALESCE(source2_scenario_tags, array())) AS union_scenario_tags
    ,local_date

    ,sum(if(antifraud_tag is null, order_cnt, 0)) as rm_fraud_order_cnt
    ,sum(order_cnt) as order_cnt
    ,sum(if(antifraud_tag is null, gmv, 0)) as rm_fraud_gmv
    ,sum(gmv) as gmv
from
    behavior_data_${grass_region_without_quote} as t1
left join
    order_antifraud_tag_${grass_region_without_quote} as t2
on
    t1.order_id = t2.order_id
group by 1, 2, 3, 4
;

--sql_divide_splitter--
cache table exp_group_data_filter_${grass_region_without_quote} OPTIONS ('storageLevel' 'MEMORY_AND_DISK_SER') as
select
    exp_group_id
    ,is_ads
    ,union_scenario_tags
    ,t1.local_date

    ,sum(rm_fraud_order_cnt) as rm_fraud_order_cnt
    ,sum(order_cnt) as order_cnt
    ,sum(rm_fraud_gmv) as rm_fraud_gmv
    ,sum(gmv) as gmv
from
    behavior_data_joined_${grass_region_without_quote} as t1
inner join
    selected_user_exps_${grass_region_without_quote} as t2
on
    t1.user_id = t2.user_id
    and t1.local_date = t2.local_date
group by 1, 2, 3, 4;

--sql_divide_splitter--
CREATE TEMPORARY VIEW feature_tag_data_${grass_region_without_quote} AS
SELECT
    local_date
    ,exp_group_id
    ,is_ads
    ,scenario_tag
    ,sum(rm_fraud_order_cnt) as rm_fraud_order_cnt
    ,sum(order_cnt) as order_cnt
    ,sum(rm_fraud_gmv) as rm_fraud_gmv
    ,sum(gmv) as gmv
FROM exp_group_data_filter_${grass_region_without_quote}
LATERAL VIEW EXPLODE(union_scenario_tags) AS scenario_tag
GROUP BY
    local_date
    ,exp_group_id
    ,is_ads
    ,scenario_tag
;

--sql_divide_splitter--
insert overwrite table ${schema}.dws_sr_data_warehouse_platform_antifraud_exp_level_order_metrics_1d
partition(exp_type = 'assign_log_join', grass_region = ${grass_region}, local_date)

SELECT
    exp_group_id
    ,is_ads
    ,'__ALL__' AS scenario_tag
    ,sum(rm_fraud_order_cnt) as rm_fraud_order_cnt
    ,sum(order_cnt) as order_cnt
    ,sum(rm_fraud_gmv) as rm_fraud_gmv
    ,sum(gmv) as gmv

    ,local_date
FROM exp_group_data_filter_${grass_region_without_quote}
GROUP BY
    exp_group_id
    ,is_ads
    ,local_date

UNION ALL

SELECT
    exp_group_id
    ,is_ads
    ,scenario_tag
    ,sum(rm_fraud_order_cnt) as rm_fraud_order_cnt
    ,sum(order_cnt) as order_cnt
    ,sum(rm_fraud_gmv) as rm_fraud_gmv
    ,sum(gmv) as gmv

    ,local_date
FROM feature_tag_data_${grass_region_without_quote}
GROUP BY
    exp_group_id
    ,is_ads
    ,scenario_tag
    ,local_date
;
